package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity; import jakarta.persistence.*; import java.math.*; import java.util.*;
@Entity @Table(name="rsp_evaluation_policy_criterion",uniqueConstraints=@UniqueConstraint(name="uk_rsp_evaluation_criterion_code",columnNames={"agency_id","stage_id","normalized_code"}))
public class EvaluationCriterion extends RspAuditedEntity {
 @Column(name="policy_id",nullable=false,length=36) private String policyId; @Column(name="stage_id",nullable=false,length=36) private String stageId; @Column(nullable=false,length=80) private String code; @Column(name="normalized_code",nullable=false,length=80) private String normalizedCode; @Column(nullable=false,length=300) private String label; @Column(length=2000) private String instructions; @Column(nullable=false,precision=7,scale=4) private BigDecimal weight; @Column(name="maximum_score",precision=12,scale=4) private BigDecimal maximumScore; @Column(name="requires_remarks",nullable=false) private boolean requiresRemarks; @Column(name="display_order",nullable=false) private int displayOrder;
 protected EvaluationCriterion(){}
 public EvaluationCriterion(String agency,String policy,String stage,String code,String label,String instructions,BigDecimal weight,BigDecimal max,boolean remarks,int order){super(agency);policyId=requiredText(policy,"policyId");stageId=requiredText(stage,"stageId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.label=requiredText(label,"label");this.instructions=optionalText(instructions);this.weight=Objects.requireNonNull(weight);maximumScore=max;requiresRemarks=remarks;displayOrder=order;if(order<0||weight.signum()<0||weight.compareTo(new BigDecimal("100"))>0||max!=null&&max.signum()<=0)throw new IllegalArgumentException("Invalid evaluation criterion values");}
 public String getPolicyId(){return policyId;} public String getStageId(){return stageId;} public String getCode(){return code;} public String getLabel(){return label;} public String getInstructions(){return instructions;} public BigDecimal getWeight(){return weight;} public BigDecimal getMaximumScore(){return maximumScore;} public boolean isRequiresRemarks(){return requiresRemarks;} public int getDisplayOrder(){return displayOrder;}
}
